sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartInstance = null;

    $scope.anoSelecionado = "";
    $scope.bimestreSelecionado = "";
    $scope.exibirGrafico = false;

    function carregarDadosDoServer() {
        var filtros = {
            ano: $scope.anoSelecionado || "",
            bimestre: $scope.bimestreSelecionado || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var listaDados = response.data.dadosGraficoPrimario || [];
            inicializarGrafico(listaDados);
        });
    }

    $rootScope.$on('filtroAnoSelecionado', function(event, ano) {
        $scope.anoSelecionado = ano;
        carregarDadosDoServer();
    });

    $rootScope.$on('filtroBimestreSelecionado', function(event, bimestre) {
        $scope.bimestreSelecionado = bimestre;
        carregarDadosDoServer();
    });

    carregarDadosDoServer();

    function inicializarGrafico(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartInstance) {
                chartInstance.destroy();
                chartInstance = null;
            }
            $scope.exibirGrafico = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGrafico = true;
        $scope.$applyAsync();

        var labels = [];
        var receitaData = [];
        var despesaData = [];

        for (var i = 0; i < listaDados.length; i++) {
            labels.push(listaDados[i].ano);
            receitaData.push(listaDados[i].receita / 1);
            despesaData.push(listaDados[i].despesa / 1);
        }

        var contexto = document.getElementById('graficoResultadoPrimario').getContext('2d');

        if (chartInstance) {
            chartInstance.destroy();
        }

        chartInstance = new Chart(contexto, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Receita Primária Total',
                        data: receitaData,
                        backgroundColor: '#4A75B1',
                        borderColor: '#4A75B1',
                        borderWidth: 1
                    },
                    {
                        label: 'Despesa Primária Total',
                        data: despesaData,
                        backgroundColor: '#6BB7F0',
                        borderColor: '#6BB7F0',
                        borderWidth: 1
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valor em R$'
                        },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + value.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};

    var anoFiltro = input.ano || "";
    var bimestreFiltro = input.bimestre || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_resultado_primario');
		gr.addQuery('u_rpps', true);

    if (anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }

    if (bimestreFiltro !== "") {
        gr.addQuery('u_bimestre', bimestreFiltro);
    }

    gr.orderBy('u_ano');
    gr.query();

    var dadosAgrupados = {};

    while (gr.next()) {
        var ano = gr.getValue('u_ano');
        var bimestre = gr.getValue('u_bimestre');
        var receitaRaw = gr.getValue('u_receita_primaria_total') || "0";
        var despesaRaw = gr.getValue('u_despesa_primaria_total') || "0";

        // Convertendo valores formatados "4.092.955.668,73" -> 4092955668.73
        function parseValor(valorStr) {
            return parseFloat(valorStr) || 0;
        }

        var receita = parseValor(receitaRaw);
        var despesa = parseValor(despesaRaw);

        if (bimestreFiltro !== "") {
            // Se filtro de bimestre existe, não soma, lista normal
            dadosAgrupados[ano + '-' + bimestre + '-' + Math.random()] = {
                ano: ano,
                bimestre: bimestre,
                receita: receita,
                despesa: despesa
            };
        } else {
            // Se não tem filtro de bimestre, agrupa por ano somando receita e despesa
            if (!dadosAgrupados[ano]) {
                dadosAgrupados[ano] = {
                    ano: ano,
                    receita: 0,
                    despesa: 0
                };
            }
            dadosAgrupados[ano].receita += receita;
            dadosAgrupados[ano].despesa += despesa;
        }
    }

    var listaDados = [];
    for (var key in dadosAgrupados) {
        listaDados.push(dadosAgrupados[key]);
    }

    // Ordena por ano
    listaDados.sort(function(a, b) {
        return a.ano.localeCompare(b.ano);
    });

    data.dadosGraficoPrimario = listaDados;
})();
